window.kbPageData["views/entry/k-ea790c55298699b1"] = {"key":"entry/k-ea790c55298699b1","state":{"route":"entry/k-ea790c55298699b1"},"node":{"id":"k-ea790c55298699b1","mode":"k","title":"温室二氧化碳施肥","type":"原理与机制","domain":"科技","reading":"","intro":"","priority":100,"aliases":["光照条件下适量补充二氧化碳可促进作物光合作用和增产"],"qs":["国考 2025 副省级 行测#33"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"directorySummary":"二氧化碳是作物进行光合作用的原料。当光照等条件适宜且二氧化碳供应限制光合作用时，适量补充二氧化碳可促进有机物合成，并有助于增产。","review":{"definition":"二氧化碳是作物进行光合作用的原料。当光照等条件适宜且二氧化碳供应限制光合作用时，适量补充二氧化碳可促进有机物合成，并有助于增产。","explanation":"D项说的是栽培过程中通入“适量”的二氧化碳。在有足够光照且作物能利用新增二氧化碳的条件下，补充原料可提高光合速率，有利于产量增加，因此D项成立。","references":[],"evidence":"在作物栽培过程中通入适量的二氧化碳可以提高作物产量","disposition":"独立词条","basis":"据原题和解析编释。"}},"questions":{"国考 2025 副省级 行测#33":{"paper":"国考 2025 副省级 行测","n":33,"mod":"常识判断","src":["ffe12c35a46d4df574ec.pdf",5],"asrc":["ff0b352b44d417525086.pdf",12],"card":"926ac0875057e80f587f5fef","links":[{"id":"k-ea790c55298699b1","role":"直接考查","why":"二氧化碳参与光合作用，解释了适量补充有助于作物合成有机物。"}]}},"terms":{},"references":{},"topics":[],"units":{"k-ea790c55298699b1":[["国考 2025 副省级 行测#33"]]}};
